<template>
  <div>
    <el-dialog v-model="workspaceVisible" :title="current.name ? current.name+' · 客户工作台' : '客户工作台'" width="min(1260px,96vw)" destroy-on-close>
      <div class="customer-banner"><div><strong>{{ current.name }}</strong><span>{{ current.phone }}</span><el-tag size="small">{{ statusName(current.status) }}</el-tag></div><div><el-tag v-for="tag in current.tags || []" :key="tag" size="small" class="small-tag">{{ tag }}</el-tag><el-button v-if="current.status !== 'DEAL'" size="small" @click="changeStatus(current)">{{ current.status === 'ACTIVE' ? '暂停跟进' : '恢复跟进' }}</el-button><el-button v-if="isAdmin" size="small" @click="openAssignment">交接负责人</el-button></div></div>
      <el-tabs v-model="activeTab">
        <el-tab-pane name="demand" label="购房需求与房源推荐">
          <div class="matching-layout">
            <section class="demand-pane"><h3>购房需求</h3><el-form label-position="top" size="default">
              <el-form-item label="意向区域"><el-select v-model="demand.districts" multiple filterable allow-create style="width:100%" placeholder="留空表示不限"><el-option v-for="d in districts" :key="d" :label="d" :value="d" /></el-select></el-form-item>
              <el-form-item label="总预算（万元）"><div class="range-input"><el-input v-model="demand.minWan" placeholder="最低不限" /><span>至</span><el-input v-model="demand.maxWan" placeholder="最高不限" /></div></el-form-item>
              <el-form-item label="建筑面积（㎡）"><div class="range-input"><el-input-number v-model="demand.minArea" :min="0" :precision="2" :controls="false" placeholder="最小不限" /><span>至</span><el-input-number v-model="demand.maxArea" :min="0" :precision="2" :controls="false" placeholder="最大不限" /></div></el-form-item>
              <el-form-item label="室数"><div class="range-input"><el-input-number v-model="demand.minRooms" :min="1" :max="50" :controls="false" placeholder="最少不限" /><span>至</span><el-input-number v-model="demand.maxRooms" :min="1" :max="50" :controls="false" placeholder="最多不限" /></div></el-form-item>
              <el-form-item label="装修"><el-select v-model="demand.decoration" clearable placeholder="不限" style="width:100%"><el-option v-for="(name,key) in decorations" :key="key" :label="name" :value="key" /></el-select></el-form-item>
              <el-form-item label="预计购房日期"><el-date-picker v-model="demand.expectedPurchaseDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item>
              <el-form-item label="需求说明"><el-input v-model="demand.notes" type="textarea" :rows="2" maxlength="5000" /></el-form-item>
            </el-form><el-button type="primary" :loading="savingDemand" @click="saveDemand">保存需求并匹配</el-button><p class="hint">只对已填写条件评分，未填写项目不参与计算。需求说明用于人工沟通，不自动推断条件。</p></section>
            <section class="recommend-pane">
              <div class="matching-controls"><el-select v-model="mode" @change="loadRecommendations" style="width:155px"><el-option label="完全符合条件" value="STRICT" /><el-option label="包含可协商方案" value="FLEXIBLE" /></el-select><el-select v-model="priority" @change="loadRecommendations" style="width:140px"><el-option label="均衡排序" value="BALANCED" /><el-option label="预算优先" value="BUDGET" /><el-option label="面积优先" value="SPACE" /></el-select><el-button :disabled="selected.length<2" @click="compareVisible=true">对比 {{ selected.length }}/3</el-button></div>
              <el-alert v-if="demandDirty" title="需求已修改，点击“保存需求并匹配”后更新推荐。当前结果依据上次保存的需求。" type="warning" :closable="false" />
              <p class="matching-basis">规则符合度用于解释已填写条件，分值不代表成交概率。仅比较同店、当前权限内的有效在售房源。</p>
              <div v-if="recommendations.demandConfigured" class="match-counts"><span>候选 {{ recommendations.candidateCount }}</span><span>完全符合 {{ recommendations.strictCount }}</span><span>有资料待确认 {{ recommendations.informationMissingCount }}</span></div>
              <el-alert v-if="recommendations.truncated" title="当前最多分析5000套候选房源，请进一步细化业务范围。" type="info" :closable="false" />
              <el-table ref="matchTable" :data="recommendations.records || []" row-key="id" v-loading="matching" @selection-change="selectionChanged" max-height="530">
                <el-table-column type="selection" width="42" />
                <el-table-column label="房源及差异" min-width="260"><template #default="{row}"><div class="match-house">{{ row.communityName }} <small>{{ row.district }}</small></div><p class="house-facts">{{ row.buildingAreaSqm }}㎡ · {{ row.rooms ?? '未知' }}室 · {{ moneyWan(row.listingPriceYuan) }}万元</p><div class="reason-tags"><el-tag v-for="reason in row.matchReasons" :key="reason" size="small" type="success">{{ reason }}</el-tag></div><p v-for="gap in row.matchGaps" :key="gap" class="gap-text">{{ gap }}</p><p v-for="unknown in row.missingInformation" :key="unknown" class="hint">{{ unknown }}</p><small v-if="Number(row.budgetOverrunYuan)>0" class="gap-text">超最高预算 {{ moneyWan(row.budgetOverrunYuan) }}万元</small></template></el-table-column>
                <el-table-column label="符合度" width="100"><template #default="{row}"><strong class="score">{{ row.matchScore }}分</strong><small class="tier">{{ {EXACT:'完全符合',NEGOTIABLE:'需协商',NEEDS_CONFIRMATION:'资料待确认'}[row.matchTier] }}</small></template></el-table-column>
                <el-table-column label="下一步" width="125"><template #default="{row}"><el-button size="small" :disabled="current.status !== 'ACTIVE'" @click="book(row)">预约带看</el-button></template></el-table-column>
                <template #empty><el-empty :image-size="65" :description="recommendations.demandConfigured ? '没有完全符合的房源，可切换可协商方案或调整需求' : '先填写并保存购房需求，系统再给出有依据的推荐'" /></template>
              </el-table>
            </section>
          </div>
        </el-tab-pane>
        <el-tab-pane name="follow" label="跟进与联系计划"><div class="follow-layout"><el-form label-position="top"><el-form-item label="联系方式"><el-select v-model="follow.type"><el-option label="电话" value="PHONE" /><el-option label="微信" value="WECHAT" /><el-option label="到访" value="VISIT" /><el-option label="其他" value="OTHER" /></el-select></el-form-item><el-form-item label="沟通记录"><el-input v-model="follow.content" type="textarea" :rows="4" maxlength="5000" placeholder="记录客户关注点、异议和下一步安排" /></el-form-item><el-form-item label="下次联系（选填）"><el-date-picker v-model="follow.nextContactAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" /></el-form-item><el-button type="primary" :loading="savingFollow" @click="saveFollow">保存跟进</el-button></el-form><div><el-empty v-if="!followUps.length" description="还没有跟进记录" :image-size="65" /><article v-for="item in followUps" :key="item.id" class="follow-entry"><div>{{ timeText(item.createdAt) }} · {{ {PHONE:'电话',WECHAT:'微信',VISIT:'到访',OTHER:'其他'}[item.contactType] || item.contactType }}</div><p>{{ item.content }}</p><small v-if="item.nextContactAt">下次联系：{{ timeText(item.nextContactAt) }}</small></article></div></div></el-tab-pane>
      </el-tabs>
    </el-dialog>

    <el-dialog v-model="compareVisible" title="房源差异对比" width="min(1100px,95vw)"><div class="compare-wrap"><table class="compare-table"><thead><tr><th>比较项目</th><th v-for="row in selected" :key="row.id">{{ row.communityName }}</th></tr></thead><tbody><tr v-for="field in compareFields" :key="field.key"><th>{{ field.label }}</th><td v-for="row in selected" :key="row.id">{{ compareValue(row,field.key) }}</td></tr></tbody></table></div><p class="hint">挂牌价格来自房源资料；符合度仅依据当前已保存需求和所选排序策略。</p></el-dialog>
    <el-dialog v-model="assignmentVisible" title="交接客户负责人" width="450px"><el-form label-position="top"><el-form-item label="同店经纪人"><el-select v-model="assignment.brokerId" style="width:100%"><el-option v-for="b in assignmentBrokers" :key="b.id" :label="b.brokerName || b.name" :value="b.id" /></el-select></el-form-item><el-form-item label="交接原因"><el-input v-model="assignment.reason" type="textarea" maxlength="500" /></el-form-item></el-form><template #footer><el-button @click="assignmentVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveAssignment">确认交接</el-button></template></el-dialog>
  </div>
</template>
<script>
import { errorText, moneyWan, nullableNumber, wanToYuan } from '@/business'
const blankDemand = () => ({ districts: [], minWan: '', maxWan: '', minArea: null, maxArea: null, minRooms: null, maxRooms: null, decoration: '', expectedPurchaseDate: null, notes: '' })
export default {
  props: { customerId: [String, Number] },
  emits: ['changed', 'closed'],
  data() { return {
    workspaceVisible: false, activeTab: 'demand', current: {}, demand: blankDemand(), demandSnapshot: '', recommendations: {}, selected: [], mode: 'STRICT', priority: 'BALANCED', matching: false, savingDemand: false, requestSequence: 0,
    follow: { type: 'PHONE', content: '', nextContactAt: null }, followUps: [], savingFollow: false, compareVisible: false,
    assignmentVisible: false, assignmentBrokers: [], assignment: { brokerId: '', reason: '' }, saving: false,
    districts: ['上城','拱墅','西湖','滨江','余杭','临平','萧山','钱塘','富阳','临安'],
    decorations: { FINE:'精装',SIMPLE:'简装',ROUGH:'毛坯',OTHER:'其他' },
    compareFields: [{key:'district',label:'区域'},{key:'listingPriceYuan',label:'挂牌总价（万元）'},{key:'budgetOverrunYuan',label:'超最高预算（万元）'},{key:'unitPriceYuanSqm',label:'挂牌单价（元/㎡）'},{key:'buildingAreaSqm',label:'建筑面积（㎡）'},{key:'layout',label:'室 / 厅 / 卫'},{key:'decoration',label:'装修'},{key:'hasElevator',label:'电梯'},{key:'matchScore',label:'规则符合度'},{key:'matchGaps',label:'待协商差异'},{key:'missingInformation',label:'待确认资料'}],
  } },
  computed: { isAdmin() { return this.$store.state.role === 'ADMIN' }, demandDirty() { return JSON.stringify(this.demand) !== this.demandSnapshot } },
  watch: {
    customerId: { immediate: true, handler(id) { if (id) this.openWorkspace({id}) } },
    workspaceVisible(value) { if (!value) this.$emit('closed') }
  },
  beforeUnmount() { this.requestSequence++ },
  methods: {
    moneyWan,
    load() { this.$emit('changed') },
    statusName(value) { return {ACTIVE:'跟进中',DEAL:'已成交',INACTIVE:'暂不跟进'}[value] || value },
    timeText(value) { return value ? String(value).replace('T',' ').slice(0,16) : '未安排' },
    setDemand(source={}) { this.demand={districts:[...(source.districts||[])],minWan:source.minPrice==null?'':String(Number(source.minPrice)/10000),maxWan:source.maxPrice==null?'':String(Number(source.maxPrice)/10000),minArea:source.minArea??null,maxArea:source.maxArea??null,minRooms:source.minRooms??null,maxRooms:source.maxRooms??null,decoration:source.decoration==='UNKNOWN'?'':source.decoration||'',expectedPurchaseDate:source.expectedPurchaseDate||null,notes:source.notes||''};this.demandSnapshot=JSON.stringify(this.demand) },
    async openWorkspace(row) { const sequence=++this.requestSequence;try{const [r,f]=await Promise.all([this.$axios.get('/customers/'+row.id),this.$axios.get('/customers/'+row.id+'/follow-ups')]);if(sequence!==this.requestSequence)return;this.current=r.data.data;this.setDemand(this.current.demand||{});this.followUps=f.data.data||[];this.follow={type:'PHONE',content:'',nextContactAt:null};this.activeTab='demand';this.recommendations={};this.selected=[];this.mode='STRICT';this.priority='BALANCED';this.workspaceVisible=true;await this.loadRecommendations()}catch(e){if(sequence===this.requestSequence){this.$message.error(errorText(e));this.$emit('closed')}} },
    async saveDemand() { this.savingDemand=true;try{const d=this.demand;const body={districts:d.districts,minPrice:wanToYuan(d.minWan),maxPrice:wanToYuan(d.maxWan),minArea:nullableNumber(d.minArea),maxArea:nullableNumber(d.maxArea),minRooms:nullableNumber(d.minRooms),maxRooms:nullableNumber(d.maxRooms),decoration:d.decoration||null,expectedPurchaseDate:d.expectedPurchaseDate||null,notes:d.notes,version:this.current.version};const r=await this.$axios.put('/customers/'+this.current.id+'/demand',body);this.current=r.data.data;this.setDemand(this.current.demand);await this.loadRecommendations();this.$message.success('需求已保存，推荐已更新');this.load()}catch(e){this.$message.error(errorText(e))}finally{this.savingDemand=false} },
    async loadRecommendations() { if(!this.current.id)return;const sequence=++this.requestSequence;this.matching=true;try{const r=await this.$axios.get('/customers/'+this.current.id+'/recommendations',{params:{mode:this.mode,priority:this.priority,limit:50}});if(sequence!==this.requestSequence)return;this.recommendations=r.data.data;this.selected=[];this.$refs.matchTable?.clearSelection()}catch(e){if(sequence===this.requestSequence)this.$message.error(errorText(e))}finally{if(sequence===this.requestSequence)this.matching=false} },
    selectionChanged(rows) { if(rows.length>3){this.$refs.matchTable?.toggleRowSelection(rows[rows.length-1],false);this.$message.info('每次最多对比3套房源');return}this.selected=rows },
    compareValue(row,key) { if(['listingPriceYuan','budgetOverrunYuan'].includes(key))return moneyWan(row[key]);if(key==='layout')return [row.rooms??'未知',row.halls??'未知',row.bathrooms??'未知'].join(' / ');if(key==='decoration')return this.decorations[row.decoration]||'待确认';if(key==='hasElevator')return row.hasElevator==null?'待确认':row.hasElevator?'有':'无';if(Array.isArray(row[key]))return row[key].join('；')||'无';return row[key]??'待确认' },
    async book(row) { try{if(row.matchTier!=='EXACT')await this.$confirm([...row.matchGaps,...row.missingInformation].join('；')+'。确认已与客户沟通，继续预约？','核对房源差异',{type:'warning'});this.workspaceVisible=false;this.$router.push({path:'/showing',query:{houseId:row.id,customerId:this.current.id,brokerId:row.brokerId}})}catch{} },
    async saveFollow() { if(!this.follow.content.trim())return this.$message.warning('请填写沟通记录');this.savingFollow=true;try{await this.$axios.post('/customers/'+this.current.id+'/follow-ups',{...this.follow,nextContactAt:this.follow.nextContactAt||null});const [r,f]=await Promise.all([this.$axios.get('/customers/'+this.current.id),this.$axios.get('/customers/'+this.current.id+'/follow-ups')]);this.current=r.data.data;this.followUps=f.data.data;this.follow={type:'PHONE',content:'',nextContactAt:null};this.$message.success('跟进记录已保存');this.load()}catch(e){this.$message.error(errorText(e))}finally{this.savingFollow=false} },
    async openAssignment() { try{const r=await this.$axios.get('/brokers',{params:{storeId:this.current.storeId}});this.assignmentBrokers=(r.data.data||[]).filter(b=>String(b.id)!==String(this.current.brokerId));this.assignment={brokerId:'',reason:''};this.assignmentVisible=true}catch(e){this.$message.error(errorText(e))} },
    async saveAssignment() { if(!this.assignment.brokerId||!this.assignment.reason.trim())return this.$message.warning('请选择新负责人并填写原因');this.saving=true;try{await this.$axios.put('/customers/'+this.current.id+'/assignment',{...this.assignment,version:this.current.version});this.assignmentVisible=false;const r=await this.$axios.get('/customers/'+this.current.id);this.current=r.data.data;this.$message.success('负责人已交接');this.load()}catch(e){this.$message.error(errorText(e))}finally{this.saving=false} },
    async changeStatus(row) { try{const r=await this.$prompt('请填写调整原因','客户跟进状态',{inputValidator:v=>!!v?.trim()&&v.length<=500||'请填写500字以内的原因'});const d=await this.$axios.get('/customers/'+row.id);await this.$axios.put('/customers/'+row.id+'/status',{status:row.status==='ACTIVE'?'INACTIVE':'ACTIVE',reason:r.value,version:d.data.data.version});const latest=await this.$axios.get('/customers/'+row.id);this.current=latest.data.data;this.load()}catch(e){if(e!=='cancel'&&e!=='close')this.$message.error(errorText(e))} },
  }
}
</script>
<style scoped>
.pages{margin-top:16px}.small-tag{margin:2px 4px 2px 0}.muted,.hint{color:#828c98;font-size:12px;line-height:1.7}.hint{display:block}.overdue{color:#a67538}.customer-banner{display:flex;justify-content:space-between;gap:15px;align-items:center;padding:0 0 15px;flex-wrap:wrap}.customer-banner>div{display:flex;align-items:center;gap:12px}.customer-banner strong{font-size:19px}.customer-banner span{color:#737d89}.matching-layout{display:grid;grid-template-columns:320px minmax(0,1fr);gap:24px}.demand-pane{border:1px solid #e3e7eb;padding:17px;border-radius:9px;background:#fafbfc}.demand-pane h3{margin:0 0 18px;font-size:16px}.demand-pane .el-form-item{margin-bottom:15px}.range-input{display:flex;align-items:center;gap:8px;width:100%}.range-input .el-input,.range-input .el-input-number{width:calc(50% - 14px);flex:1;min-width:0}.range-input>span{color:#929ba6;font-size:12px}.recommend-pane{min-width:0}.matching-controls{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:14px}.matching-basis{font-size:12px;color:#7a8491;line-height:1.7}.match-counts{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;color:#64707e;margin:13px 0}.match-house{font-weight:600;color:#3e4753}.match-house small{font-weight:400;margin-left:6px;color:#87919c}.house-facts{font-size:12px;margin:6px 0;color:#717c89}.reason-tags{display:flex;gap:4px;flex-wrap:wrap}.gap-text{font-size:12px;color:#996f35;line-height:1.65;margin:5px 0}.score{font-size:19px;color:#8c6a34}.tier{display:block;font-size:11px;color:#818b97;margin-top:5px}.follow-layout{display:grid;grid-template-columns:330px minmax(0,1fr);gap:28px}.follow-entry{padding:15px 0;border-bottom:1px solid #e5e8eb}.follow-entry>div,.follow-entry small{font-size:12px;color:#7f8996}.follow-entry p{white-space:pre-wrap;line-height:1.8;color:#495360}.compare-wrap{overflow:auto}.compare-table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:13px}.compare-table th,.compare-table td{border:1px solid #e4e7eb;padding:13px;line-height:1.7;word-break:break-word;vertical-align:top}.compare-table th{background:#f7f8fa;color:#626f7d;font-weight:500}.compare-table th:first-child{width:150px}@media(max-width:900px){.matching-layout,.follow-layout{grid-template-columns:1fr}.customer-banner>div{flex-wrap:wrap}}
</style>
